"""Ponte entre o planner do site e o motor. Roda no navegador via Pyodide (e em Python normal, para os testes).

    sheet(json_do_planner) -> json com a ficha do personagem

O planner manda o próprio estado (S) com a gear já normalizada pelo JS:
  gear[slot].slots = slots naturais, alma só se o slot de alma estiver aberto.
Campos da fase 1 no estado do planner:
  lv, base{stat}, run{stat}, skl{skill: nível}, acct{marks, boons, gods{deus: n}, upFull, ups{id: nível}, stew}
"""
import json
from calc.engine.game import Game
from calc.engine.player import state, job_path, STATS
from calc.engine.survival import survival
from calc.engine.festival import run as festival_run, festival, emperiums
from calc.engine.caster import caster_avg
from calc.engine.run import estimates, to_acct

_GAME = {}
GRADE_MIN_REFINE = 10   # planner D.rules.gradeMinRefine (Equipment.grade: grade só vale com +10)


def game(version=None):
    if version not in _GAME: _GAME[version] = Game(version)
    return _GAME[version]


ITEMS = {}


def _nat_slots(g):
    """Planner rule (same as planner.js natSlots): legendary, unique, Tower wings, souls and faces drop with 0 slots
    (Equipment.make(id, 0)); fixed_slots items keep theirs; Epic items count as 3."""
    d = ITEMS.get("sword_wings" if g["id"] == "hel_wings" else g["id"], {})
    if "fixed_slots" in d: return int(d["fixed_slots"])
    if d.get("legendary") or d.get("wings") or d.get("soul_of") or (d.get("slot") == "low" and d.get("face")): return 0
    return 3


def _item(s, g):
    it = {"id": g["id"], "cards": [c for c in g.get("cards", []) if c], "slots": _nat_slots(g),
          "refine": int(g.get("refine", 0)), "trait": g.get("trait") or None}
    if it["id"] == "hel_wings": it.update(id="sword_wings", hel=True)          # o planner trata as Wings of Hel como item próprio
    it["grade"] = int(g.get("grade", 0)) if it["refine"] >= GRADE_MIN_REFINE else 0
    lines = []
    for l in g.get("pot", []) or []:
        if not l or not l.get("k"): continue
        t = int(l.get("t", 1))
        lines.append({"k": l["k"], "t": min(t, 3), "p": t >= 4})              # planner: tier 4 = Perfeito (7★)
    if lines: it["pot"] = {"lines": lines}
    return it


def planner_to_build(g, s):
    ITEMS.update(g.G["ITEMS"])
    a = s.get("acct") or {}
    ups = {}
    for uid, u in g.G["UPGRADES"].items():
        ups[uid] = u.get("max", 0) if a.get("upFull", True) else int((a.get("ups") or {}).get(uid, 0))
    AL = g.G["ALTARS"]
    gods = [god for god, n in (a.get("gods") or {}).items() if god in AL and "karma" not in AL[god] for _ in range(int(n or 0))]
    kalt = [god for god, n in (a.get("gods") or {}).items() if god in AL and "karma" in AL[god] for _ in range(int(n or 0))]
    top = int(s.get("towerTop") or 0)
    power = sum(1 for fl, kind in TOWER_REWARDS if kind == "power" and fl <= top) * TOWER_POWER
    base = {k: int((s.get("base") or {}).get(k, 0)) for k in STATS}
    run = {k: int((s.get("run") or {}).get(k, 0)) for k in STATS}
    skills = evolve({k: int(v) for k, v in (s.get("skl") or {}).items() if int(v or 0) > 0 and k in g.G["SKILLS"]}, g, s.get("noEvo") or ())
    return {"job": job_path(g, s["cls"], bool(s.get("reborn"))),
            "gear": {slot: _item(s, it) for slot, it in (s.get("gear") or {}).items() if it and it.get("id")},
            "album": list(s.get("album") or []), "pet": s.get("pet") or None,
            "dishes": list(s.get("dishes") or [])[: int(s.get("chef") or 1)], "pacts": list(s.get("pacts") or []),
            "skills": skills, "base": base, "stats": {k: base[k] + run[k] for k in STATS}, "L": int(s.get("lv") or 1),
            "acct": {"path": "light" if a.get("path") == "light" else "dark", "marks": int(a.get("marks") or 0), "boons": int(a.get("boons") or 0),
                     "gods": gods, "karma_altars": kalt,
                     "upgrades": ups, "tower_power": power},
            "stew_hp": float(a.get("stew") or 0), "max_skills": 6}


def evolve(skills, g, keep=()):
    """player.gd::can_evolve/evolve/evolved_level: skill no nível MAX_SKILL_LEVEL+ com a passiva da evolução vira o EX,
    com nível 1 + (nível − MAX_SKILL_LEVEL). No planner o jogador digita o total de níveis pegos na skill.
    A evolução é uma escolha ao subir de nível (choice kind "evolve"), não automática: skills em keep (planner noEvo) não evoluem."""
    top = g.K["MAX_SKILL_LEVEL"]; out = dict(skills)
    for sid, lv in skills.items():
        if sid in keep: continue
        ev = g.G.get("EVOLUTIONS", {}).get(sid)
        if ev and lv >= top and ev["passive"] in skills and ev["to"] in g.G["SKILLS"]:
            out.pop(sid); out[ev["to"]] = max(out.get(ev["to"], 0), 1 + (lv - top))
    return out


# torre: andares de poder dão +10% dano e HP (planner D.rules.towerRewards / towerPower)
TOWER_REWARDS = [(10, "power"), (20, "legend"), (30, "power"), (40, "legend"), (50, "power"), (60, "legend"), (70, "power"),
                 (80, "legend"), (90, "power"), (100, "legend")]
TOWER_POWER = 0.1


def sheet_from_build(g, b):
    st = state(g, b)
    sv = survival(g, st, b)
    m, e = st["mods"], st["effects"]
    area_raw = g.K["INT_AREA"] * max(st["eff"]["str"], st["eff"]["int"]) + m.get("area", 0)
    return {
        "version": g.version,
        "eff": {k: round(v, 2) for k, v in st["eff"].items()}, "stat_cap": st["stat_cap"],
        "dmg_mult": st["dmg_mult"], "dmg_pool": m.get("dmg", 0), "risk": st["risk"],
        "crit": st["crit"], "crit_dmg": st["crit_dmg"], "critf": st["critf"],
        "ultra": st["crit_dmg"] >= g.K["ULTRA_CRIT_AT"], "lethal": st["crit_dmg"] >= g.K["LETHAL_CRIT_AT"],
        "vs": st["vs"], "basic_atk": st["basic_atk"], "basic_mult": st["basic_mult"],
        "delay": st["delay"], "attacks_per_s": 1 / st["delay"], "flow": st["flow"], "power": st["power"],
        "hits_per_s": st["flow"] / st["delay"], "extra": st["extra"],
        "cd_mult": st["cd_mult"](), "haste_pct": 1 / st["cd_mult"]() - 1, "duration_mult": st["duration_mult"],
        "area": min(g.K["AREA_MAX"], area_raw), "area_over": max(0, area_raw - g.K["AREA_MAX"]), "skill_amp": st["amp"],
        "skill_base": st["skill_base"], "support": st["support"],
        "max_hp": st["max_hp"], "hits_to_die": sv["hits_to_die"], "flee": sv["flee"],
        "proc_more": st["proc_more"], "procs": [{"skill": p["skill"], "chance": p["chance"]} for p in st["procs"]],
        "signum": st["signum"], "steel": st["steel"], "melt": st["melt"],
        "free_slots": st["free"], "own_skill_bonus": st["own_skill_bonus"],
    }


def sheet(planner_json, version=None):
    try:
        g = game(version)
        return json.dumps({"ok": True, "sheet": sheet_from_build(g, planner_to_build(g, json.loads(planner_json)))})
    except Exception as ex:
        import traceback
        return json.dumps({"ok": False, "error": "%s: %s" % (type(ex).__name__, ex), "trace": traceback.format_exc()[-1500:]})


def weapon_element(g, s):
    """equipment.gd::weapon_element: the Narakusa endow overrides the weapon's own element."""
    w = (s.get("gear") or {}).get("weapon") or {}
    if not w.get("id"): return "neutral"
    return w.get("endow") or g.G["ITEMS"].get(w["id"], {}).get("element", "neutral")


def targets(version=None):
    """Emperium + every MVP (id, name, element) for the planner's target list."""
    g = game(version); M = g.G["MONSTERS"]; EL = g.G.get("MONSTER_ELEMENTS", {})
    out = [{"id": "emperium", "name": "Emperium Festival", "el": "neutral"}]
    for k, m in M.items():
        if m.get("mvp"): out.append({"id": k, "name": m.get("name", k), "el": EL.get(k, "neutral")})
    return json.dumps(out)


def mvp_hp(g, st, tid):
    """mvp_raid.gd::_spawn_boss: max_hp = max(fórmula, tank_dps(DPS medido) × 1,3 × RAID_TANK × boss_hp) × tough.
    A parte da fórmula (vida do monstro × tempo × perigo × RAID_HP_BASE × MVP_RAID_HP) fica ordens de grandeza abaixo do piso
    em builds de fim de jogo, então a vida é o piso: ~58,5 s do seu DPS medido."""
    K, A = g.K, g.A
    measured = festival(g, st, target={"el": "neutral"})["dps"] * A["RAID_DPS_SHARE"]
    boss_hp = float(g.G.get("RAIDS", {}).get(tid, {}).get("boss_hp", 1.0))
    return measured * 1.3 * K["RAID_TANK"] * boss_hp, measured, boss_hp


def mvp_fight(g, st, tid, el, cap=600.0):
    """Luta contra o MVP parado até ele morrer (no máximo cap s), com Ymir depois de RAID_YMIR_TIME s."""
    hp, measured, boss_hp = mvp_hp(g, st, tid)
    r = festival(g, st, T=cap, target={"el": el, "hp": hp, "ymir": True}, detail=True, timeline=0.25)
    fr = r["timeline"]["frames"]                       # depois de 2 min, um quadro por segundo (o planner busca por tempo)
    r["timeline"]["frames"] = [f for f in fr if f[0] <= 120 or abs(f[0] - round(f[0])) < 1e-6 or f is fr[-1]]
    return {"dps": r["dps"], "total": r["total"], "el": el, "parts": r.get("parts"), "timeline": r["timeline"], "situ_avg": r.get("situ_avg"),
            "boss_hp": hp, "boss_mult": boss_hp, "measured_dps": measured, "killed": r["killed"], "cap": cap}


def simulate(planner_json, opts_json="{}", version=None):
    """Simulate DPS: run boons from the run estimate (path + minutes) or the account fields, then the engine's festival.
    Emperium: 60 s Festival (Emperiums, averaged over pet phases). MVP: 60 s on a target that does not die (DPS)."""
    try:
        g = game(version); s = json.loads(planner_json); o = json.loads(opts_json or "{}")
        b = planner_to_build(g, s)
        est = None
        if o.get("estimate", True):
            est = estimates(g, float(o.get("minutes", 40)), o.get("path", "dark"))
            b["acct"].update(to_acct(est))
        st = state(g, b); st["weapon_el"] = weapon_element(g, s)
        tid = o.get("target", "emperium")
        if tid == "emperium":
            r = festival_run(g, st); one = festival(g, st, detail=True, timeline=0.25)
            res = {"dps": r["dps"], "total": r["total"], "emperiums": r["score"], "parts": one["parts"], "timeline": one["timeline"]}
            cz = caster_avg(g, st, b, shared=one.get("situ_avg"))   # active skills, combos, Coma, pet on the same target
            if cz["total"] > 0:
                res["parts"] = dict(res["parts"]); [res["parts"].__setitem__(k, res["parts"].get(k, 0) + v) for k, v in cz["parts"].items()]
                res["total"] = r["total"] + cz["total"]; res["dps"] = res["total"] / g.K["FESTIVAL_TIME"]
                res["emperiums"] = emperiums(g, res["total"]); res["skills_total"] = cz["total"]
        else:
            el = g.G.get("MONSTER_ELEMENTS", {}).get(tid, "neutral")
            res = mvp_fight(g, st, tid, el)
            cz = caster_avg(g, st, b, target={"el": el}, shared=res.get("situ_avg"))   # skills as extra DPS (not in the timeline)
            if cz["total"] > 0:
                T = g.K["FESTIVAL_TIME"]; res["dps"] = res["dps"] + cz["total"] / T; res["skills_dps"] = cz["total"] / T
                res["parts"] = dict(res.get("parts") or {}); [res["parts"].__setitem__(k, res["parts"].get(k, 0) + v) for k, v in cz["parts"].items()]
        res["row_el"] = {"basic": st["weapon_el"], "heal": "holy", "heal_hit": "holy", "holy_light": "holy", "lex": "holy",
                         "envenom": "poison", "poison": "poison", "bleed": "neutral", "burn": "fire"}
        for k in list(res.get("parts") or {}):
            if k not in res["row_el"]:
                head, _, rest = k.partition(":")
                base_id = (rest.split("@")[0].replace("proc:", "") if head in ("burn", "bleed", "poison", "proc", "pet") else k)
                res["row_el"][k] = {"burn": "fire", "bleed": "neutral", "poison": "poison"}.get(head) or                     (g.G["SKILLS"].get(base_id, {}).get("element", "neutral") if base_id in g.G["SKILLS"] else
                     (g.G["PETS"].get(base_id, {}).get("skill", {}).get("element", "neutral") if head == "pet" else "neutral"))
        res.update(ok=True, version=g.version, weapon_el=st["weapon_el"], acct={k: b["acct"][k] for k in ("path", "marks", "boons", "gods", "karma_altars")},
                   estimate=est, dmg_mult=st["dmg_mult"], risk=st["risk"])
        return json.dumps(res)
    except Exception as ex:
        import traceback
        return json.dumps({"ok": False, "error": "%s: %s" % (type(ex).__name__, ex), "trace": traceback.format_exc()[-1500:]})

