"""Active skills on a single standing target (Emperium Festival / MVP dummy), event by event.

Mirrors (0.2.10):
  player.gd  cooldown loop (s.cd = cooldown x cd_for), cut_cooldowns(chain_cut, capped) after each cast (SP Recovery chain_cast),
             _double_cast / double_cast_chance / multi_casts (INT_DOUBLE x INT capped at INT_DOUBLE_MAX, + double_cast,
             + Double Casting sage_double x SAGE_DOUBLE_PROF uncapped for the Professor, at most MULTI_CAST_MAX_PROF copies,
             copy i lands INT_DOUBLE_DELAY x i later), Hindsight on each basic swing (hindsight x (1+proc_chance),
             HINDSIGHT_CD, random HINDSIGHT_SKILLS at the Hindsight level, tag "hindsight": not magic, so it scales with STR
             and does not make Elemental Combos or Coma), Dragonology (_skill_amp x (1 + DRAGON_HASTE_DMG x haste lost to soft_haste)).
  skills.gd  v(field) (amp on magic damage, extra_count), _bolt (count capped at BOLTS_MAX with the rest folded into each bolt,
             bolt i at i x bolt_gap + bolt_time), _aoe_target (one hit on a lone target at +0.25 s; spider_web webs it),
             _projectile hitscan same_target (count hits 0.07 s apart), _soul_strike (gap x i + flight), _ground (ticks every
             `tick` for duration x duration_mult).
  main.gd    damage_enemy subset for a lone boss: vs_boss / Doom / vs_mvp (`st["vs"]`), boss status mark (_boss_status_mark:
             freeze/stone for min(time,STATUS_MAX_TIME)/2 s; wind on freeze, fire on stone use the status element:
             Status Combo), weak_bonus, web (WEB_FIRE on fire/water/earth/wind for WEB_FIRE_TIME), _wiz_combo (Professor
             only with the Elements Pact: a mark of one element, a magic or proc hit of another detonates it 0.05 s later for
             base x COMBO_MULT x (1+combo_dmg) x reaction share; COMBO_CAP per 0.1 s; the reaction is a neutral "wiz_combo"
             hit that goes through damage_enemy again), Lich's Bone Wand Coma on a boss (u_coma chance per magic skill hit,
             x U_COMA_BOSS_MULT for U_COMA_BOSS_TIME s, then U_COMA_BOSS_CD), pet skill (_pet_skill: dmg x MVP_PET_DMG x
             (1 + MVP_PET_LEVEL_DMG x (L-1)), one strike on a lone target, every `every` s).
Not yet: burn/bleed DoTs from skills and pets, Soul Strike detonation, card procs that cast skills, Legends/JobEngines/Uniques
damage_mult, pacts Vengeance/Agony. Crits use the expected factor st["critf"].
"""
import heapq, math, random
from .stats import skill_value as sv, soft_haste
from .festival import el_mult, emperiums

DAMAGE_TYPES = ("bolt", "aoe_target", "projectile", "soul_strike", "ground", "melee_arc", "aoe_self", "backstab", "issen",
                "jupitel", "sightrasher", "gravity", "drill", "ice_trail", "cart_cannon")


def _c(g, k):
    try: return g.K[k]
    except KeyError: return g.G[k]


def cast_hits(g, st, sid, lv, tag, bake=1.0, rng=None):
    """One cast of skill `sid` on a lone target: list of (delay, base damage, element, kind).
    Procs (tag "proc:..."): damage x proc_bake (held casts) and, above the level cap, the over_dmg_step correction (skills.gd v())."""
    G, K = g.G, g.K
    s = G["SKILLS"][sid]; eff = st["effects"]
    amp = eff.get("amp", 0.0)
    from .stats import skill_cap, overlevel_steps

    def v(f):
        x = sv(g, sid, f, lv)
        if f == "damage" and amp > 0 and s.get("magic"): x *= 1 + amp
        if f == "damage" and tag.startswith("proc:"):
            x *= bake
            top = skill_cap(g, sid)
            if "over_dmg_step" in s and lv > top:
                o = overlevel_steps(g, lv - top)
                step = s["over_dmg_step"] if s["over_dmg_step"] is not None else K["BOLT_EX_STEP"]
                x *= (1 + float(s.get("over_step", K["OVERLEVEL_STEP"])) * o) / (1 + float(step) * o)
        if f == "duration": return x * st["duration_mult"]
        if f == "count" and "count" in s: return x + int(st["mods"].get("count", 0))
        return x
    el = s.get("element", "neutral"); typ = s.get("type")
    out = []
    if typ == "bolt":
        n = int(v("count")); each = 1.0
        if n > _c(g, "BOLTS_MAX"): each = n / _c(g, "BOLTS_MAX"); n = int(_c(g, "BOLTS_MAX"))
        for i in range(n):
            out.append((i * float(s.get("bolt_gap", 0.12)) + float(s.get("bolt_time", 0.22)), v("damage") * each, el, "hit"))
    elif typ == "aoe_target":
        out.append((0.25, v("damage"), el, "web" if s.get("web_fire") else "hit"))
    elif typ == "projectile":
        n = int(v("count")) if s.get("same_target") else 1
        for i in range(n): out.append((i * 0.07, v("damage"), el, "hit"))
    elif typ == "soul_strike":
        n = max(1, int(v("count")))
        for i in range(n): out.append((float(s.get("missile_gap", 0.08)) * i + float(s.get("flight", 0.42)), v("damage"), el, "hit"))
    elif typ == "backstab":
        # skills.gd "backstab" -> main.gd::blink_chain/_blink_step on a lone target: every stab hits it, BLINK_GAP apart;
        # stab i: x(1 + 0.18 i), or BACKSTAB_X_GROWTH^min(i, cap) when the skill escalates; repeats on the same target x BS_REPEAT.
        # Not yet: lg_backstab, the escalate crit bonuses, Intimidate fear.
        n = max(1, int(v("count")))
        extra_c = int(st["mods"].get("count", 0))
        if sid.startswith("back_stab"): n = max(1, n - extra_c + min(extra_c, int(K["BS_EXTRA_STABS"])))
        if sid == "back_stab_x" and rng is not None:
            luk = float(st["eff"]["luk"]); ch = luk / (luk + K["BS_LUK_K"])
            while rng.random() < ch: n += 1; ch *= K["BS_LUK_FADE"]
        for i in range(n):
            m = pow(K["BACKSTAB_X_GROWTH"], min(i, K["BACKSTAB_X_GROWTH_CAP"])) if s.get("escalate") else 1 + 0.18 * i
            if i > 0: m *= K["BS_REPEAT"]
            out.append((i * K["BLINK_GAP"], v("damage") * m, s.get("element", "neutral"), "hit"))
    elif typ == "jupitel":
        # main.gd::jupitel: one ball per target (count) -> lone target 1 ball, `hits` hits 0.075 s apart after the flight
        for k in range(max(1, int(v("hits")))): out.append((0.15 + 0.075 * k, v("damage"), s.get("element", "wind"), "hit"))
    elif typ == "sightrasher":
        # main.gd::sightrasher: `waves` fire rings 0.28 s apart
        for w_ in range(max(1, int(s.get("waves", 1)))): out.append((0.28 * w_, v("damage"), "fire", "hit"))
    elif typ == "gravity":
        # main.gd::gravitation: a tick every 0.3 s for duration (neutral), then the implode x sk.implode
        dur = v("duration"); ticks = math.ceil(dur / 0.3)
        for k in range(ticks): out.append((0.3 * (k + 1), v("damage"), "neutral", "hit"))
        if s.get("implode"): out.append((dur + 0.3, v("damage") * float(s["implode"]), "neutral", "hit"))
    elif typ == "drill":
        # main.gd::spiral_drill: `hits` hits 0.09 s apart, x boss_mult on bosses, weapon element
        bm = float(s.get("boss_mult", 1.0))
        for k in range(max(1, int(v("hits")))): out.append((0.09 * k, v("damage") * bm, st.get("weapon_el", "neutral"), "hit"))
    elif typ == "ice_trail":
        # main.gd::ice_trail (Frost Diver): the trail reaches the lone target once
        out.append((0.2, v("damage"), s.get("element", "water"), "hit"))
    elif typ == "cart_cannon":
        # main.gd::cart_cannon/_cannon_boom: one blast on the target, weapon element (forge heat not yet)
        out.append((0.3, v("damage"), st.get("weapon_el", "neutral"), "hit"))
    elif typ == "issen":
        # skills.gd::_issen (Killing Strike): damage + (HP + shield) x hp_power; HP assumed full between casts.
        out.append((0.0, v("damage") + st["max_hp"] * v("hp_power"), s.get("element", "neutral"), "hit"))
    elif typ in ("aoe_self", "melee_arc"):
        # skills.gd::_aoe_self / _melee_arc: one hit on a lone target, melee_element (weapon element when the skill has none).
        # Zeny skills (_zeny_mult) assume the cost is paid (mult 1); Ignition Break's detonate and Bowling's packed hits: not yet.
        mel = el
        if el == "neutral" and "element" not in s and not s.get("magic") and not s.get("song"): mel = st.get("weapon_el", "neutral")
        if s.get("ignition"): mel = "fire"
        dmg = v("damage")
        out.append((0.0, dmg, mel, ("poison", v("poison")) if typ == "melee_arc" and "poison" in s else "hit"))
    elif typ == "ground":
        every = float(s.get("tick", 0.5)); t = 0.05; dur = v("duration")
        while t < dur:
            out.append((t, v("damage"), el, "hit")); t += every
    return out


def caster_avg(g, st, b, T=None, target=None, seeds=3, shared=None):
    """caster() averaged over a few seeds (multi casts, Coma and Hindsight are random)."""
    rs = [caster(g, st, b, T=T, seed=i, target=target, shared=shared) for i in range(seeds)]
    parts = {}
    for r in rs:
        for k, v in r["parts"].items(): parts[k] = parts.get(k, 0) + v / seeds
    return dict(total=sum(parts.values()), parts=parts, reactions=sum(r["reactions"] for r in rs) / seeds, dragon=rs[0]["dragon"])


def caster(g, st, b, T=None, seed=None, target=None, shared=None):
    """Damage of the build's active skills (+ Hindsight, double casts, Elemental/Status Combo, Coma, pet) in T seconds.
    shared: festival.py's mean target multiplier on the same target (Signum, Meltdown/pet frail, poison corrode, Agony,
    Vengeance, Ymir). When given, it replaces caster's own Meltdown/pet frail so the skills see the same target."""
    g.use("festival")
    G, K, A = g.G, g.K, g.A
    T = K["FESTIVAL_TIME"] if T is None else T
    rng = random.Random(A["SEED"] if seed is None else seed)
    SK = G["SKILLS"]; skills = st["skills"]; eff = st["effects"]; mods = st["mods"]; e_ = st["eff"]
    from .player import job_def
    _, job, _, _ = job_def(g, b)
    jid = job.get("id", "")
    prof = jid == "professor"
    tel = (target or {}).get("el", "neutral")
    # Dragonology: haste lost to the soft cap turns into skill damage (player.gd:1152)
    haste = K["DEX_HASTE"] * e_["dex"] + mods.get("haste", 0)
    dragon = 1 + K["DRAGON_HASTE_DMG"] * max(0.0, haste - soft_haste(g, haste)) if eff.get("dragon", 0) > 0 else 1.0
    own_bonus = st.get("own_skill_bonus", {})

    from .stats import proc_level_mult
    pp = st.get("proc_power", 0.0); steel = 1 + st.get("steel", 0.0)

    def proc_by_int(skill):
        own = skill[:-2] if skill.endswith("_x") else skill
        return "int" in G["SKILL_SCALE"].get(own, G["_SCALE_MAGIC"] if SK.get(skill, {}).get("magic") else G["_SCALE_PHYS"])

    def proc_kind(skill, when_hit):
        """player.gd own_proc_mult / proc_kind_mult."""
        k = proc_level_mult(g, st["L"]) * K["PROC_DMG"] * float(G["PROC_SKILL_DMG"].get(skill, 1.0)) * (1 + pp) * steel
        magic = proc_by_int(skill)
        if not when_hit:
            km = (st["basic_mult"] + mods.get("proc_dmg", 0) + (st["proc_int_basic"] if magic else 0)) * k
        else:
            root = K["PROC_HIT_HP_ROOT"]
            if "retaliation" in st["pacts"]: root = float(G["PACTS"]["retaliation"]["retaliate"]["hp_root"])
            km = (1 + K["STR_DMG"] * max(e_["str"], e_["vit"]) + mods.get("proc_dmg", 0) + (st["proc_int_hit"] if magic else 0)) * k \
                * (1 + math.sqrt(max(0.0, st["max_hp"])) * root)
        for sid in (skill + "_x", skill):
            if sid in skills:
                return max(km, st["skill_mult_for"](sid) * dragon * (1 + pp) * steel)
        return km

    pet_km = max(st["skill_base"] + K["INT_SKILL_DMG"] * e_[x] for x in ("str", "int")) * st["amp"] * dragon

    def kind(sid_or_tag):
        if sid_or_tag.startswith("pet:") and sid_or_tag.count(":") >= 2:      # Thanatos echo "pet:thanatos:<skill>"
            sid_or_tag = sid_or_tag.rsplit(":", 1)[1]
        elif sid_or_tag.startswith("pet:"):
            return pet_km
        if sid_or_tag.startswith("proc:"):
            body = sid_or_tag[5:]
            return proc_kind(body.split("@")[0], body.endswith("@hit"))
        sid = sid_or_tag
        base = sid[:-2] if sid.endswith("_x") else sid
        return st["skill_mult_for"](sid) * dragon * (1 + own_bonus.get(base, 0.0))

    def weights(sid):
        own = sid[:-2] if sid.endswith("_x") else sid
        return G["SKILL_SCALE"].get(own, G["_SCALE_MAGIC"] if SK[sid].get("magic") else G["_SCALE_PHYS"])

    def multi_chance(sid):
        w = weights(sid)
        pts = sum(float(w.get(k, 0)) * e_[k] for k in ("str", "int") if k in w)
        sage = 0.0; cap = K["INT_DOUBLE_MAX"]
        if eff.get("sage_double", 0) > 0 and jid in ("sage", "professor"):
            sage = eff["sage_double"] * (K["SAGE_DOUBLE_PROF"] if prof else 1.0); cap = math.inf
        return min(cap, K["INT_DOUBLE"] * pts) + eff.get("double_cast", 0) + sage

    def multi_casts(c):
        if c <= 0: return 0
        n = math.floor(c)
        if rng.random() < c - n: n += 1
        return min(n, K["MULTI_CAST_MAX_PROF"] if prof else K["MULTI_CAST_MAX"])

    combo_on = jid in _c(g, "COMBO_JOBS") or "elements" in st["pacts"]
    combo_dmg = eff.get("combo_dmg", 0.0)
    WEB_EL = set(_c(g, "WEB_ELEMENTS")); COMBO_EL = set(_c(g, "COMBO_ELEMENTS"))
    SCOMBO, SEL = G["STATUS_COMBO"], G["STATUS_ELEMENT"]
    coma_p = eff.get("u_coma", 0.0)
    situ = st["vs"]; common = st["dmg_mult"] * st["critf"]
    weak = eff.get("weak_bonus", 0.0)
    status_plus = eff.get("status_chance", 0.0)
    parts = {}
    ev = []          # (time, seq, kind, payload)
    seq = [0]

    def push(t, k, p):
        if t <= T:
            seq[0] += 1; heapq.heappush(ev, (t, seq[0], k, p))

    # ---- casting: every damaging active skill on its cooldown
    # skills.gd::cast returns false for combo_only (Chain Crush: Monk combo, festival.py) and stance (Taekwon kicks) outside their tag
    active = [sid for sid in skills if SK.get(sid, {}).get("type") in DAMAGE_TYPES and "damage" in SK[sid]
              and not SK[sid].get("combo_only") and not SK[sid].get("stance")]
    nxt = {sid: 0.0 for sid in active}; cut = {sid: 0.0 for sid in active}; due_at = {sid: -1.0 for sid in active}
    cdf = {sid: sv(g, sid, "cooldown", skills[sid]) * st["cd_mult"](float(weights(sid).get("int", 0))) for sid in active}
    chain = eff.get("chain_cast", 0.0) * (1 - min(1.0, max(0.0, eff.get("spell_focus", 0.0))))
    for sid in active: push(0.0, "cast", (sid, skills[sid], sid, True))
    # ---- Hindsight on basic swings
    hs = eff.get("hindsight", 0.0)
    FEST_PROCS = {"heal", "envenom", "holy_light"}           # festival.py simulates these three
    procs = [q for q in st.get("procs", []) if q["skill"] not in FEST_PROCS]
    procs_hit = [q for q in st.get("procs_hit", []) if q["skill"] not in FEST_PROCS]
    proc_more = 1 + eff.get("proc_chance", 0)
    pw = st["power"]
    blows = [pw] * int(round(st["mains"])) + [pw * K["BASIC_EXTRA_DMG"]] * st["extra"] + [1.0] * int(st["double"])
    if hs > 0 or procs:
        push(st["delay"], "swing", None)
    if procs_hit:
        push(0.0, "touch", None)
    p_next, p_saved, hit_cd = {}, {}, {}
    skipped = set()
    # ---- pet
    pet = st.get("pet_skill")
    melt_f = st.get("melt", 0.0) if st.get("melt", 0) > 0 else 0.0
    pet_fr = {"v": 0.0, "until": -1.0}

    def pet_parts(sk):
        out = [sk]
        if sk.get("extra"): out += pet_parts(sk["extra"])
        return out
    if pet and any(float(q.get("dmg", 0) or 0) > 0 or q.get("kind") == "echo" for q in pet_parts(pet)):
        push(0.0, "pet", None)

    mark = {"el": "", "until": -1.0}; boss_mark = {"k": "", "until": -1.0}
    web_until = -1.0; coma = {"until": -1.0, "ready": 0.0}; hs_ready = 0.0
    win = {"at": -1.0, "n": 0}
    reactions = 0

    def hit(t, base, el, tag, magic, sk_status=None, source="skill", can_crit=False):
        nonlocal web_until
        if shared is not None: sit = situ * shared
        else:
            fr = max(melt_f, pet_fr["v"] if pet_fr["until"] > t else 0.0)    # acid_frail: Meltdown (basic hits keep it up) or pet
            sit = situ * (1 + fr)
        b0 = base * sit
        em = el_mult(g, el, tel)
        boss_combo = boss_mark["k"] and boss_mark["until"] > t and SCOMBO.get(boss_mark["k"], "") == el
        share = 0.0
        if boss_combo:
            em2 = max(em, el_mult(g, el, SEL[boss_mark["k"]]))
            own = max(0.0, el_mult(g, el, tel))
            if em2 > own + 0.01: share = 1 - own / em2
            em = em2
        if weak > 0 and (el_mult(g, el, tel) > 1.01 or boss_combo): b0 *= 1 + weak
        if el in WEB_EL and web_until > t and em > 0: em *= K["WEB_FIRE"]
        if em <= 0: return
        if source == "skill" and combo_on and tag != "wiz_combo" and el in COMBO_EL and magic:
            wiz(t, el, b0)
        crit = st["critf"] if (source != "poison" or can_crit) else 1.0
        amount = b0 * st["dmg_mult"] * crit * kind(tag) * em
        if coma["until"] > t:
            parts["u_coma"] = parts.get("u_coma", 0) + amount * (K["U_COMA_BOSS_MULT"] - 1)
        if share > 0 and source != "poison":
            parts["status_combo"] = parts.get("status_combo", 0) + amount * share; amount *= 1 - share
        row = tag if source != "poison" else ("bleed" if can_crit else ("burn" if el == "fire" else "poison")) + ":" + tag
        parts[row] = parts.get(row, 0) + amount
        if source == "poison": return
        # dots.gd::on_hit for skill hits (base / again: the situational mults are applied again on each tick)
        sk_ = SK.get(tag.replace("proc:", "").split("@")[0].rsplit(":", 1)[-1], {}) if tag.count(":") != 1 or not tag.startswith("pet:") else {}
        b_dot = b0 / sit
        bc = max(float(sk_.get("burn_chance", 0.0)), eff.get("skill_burn", 0.0))
        if bc > 0 and rng.random() < bc: burn_on(t, b_dot, tag, float(sk_.get("burn_long", 1.0)))
        lc = float(sk_.get("bleed_chance", 0.0))
        if lc > 0 and rng.random() < lc: bleed_on(t, b_dot, tag, int(sk_.get("bleed_stacks", 1)))
        # after the hit: Coma roll (uniques.gd:2876, magic skill hits only, not procs / hindsight / reactions)
        if coma_p > 0 and magic and tag in SK and SK[tag].get("magic") and t >= coma["ready"] and rng.random() < coma_p:
            coma["until"] = t + K["U_COMA_BOSS_TIME"]; coma["ready"] = coma["until"] + K["U_COMA_BOSS_CD"]
        if sk_status:
            st_kind, chance, st_time = sk_status
            if chance > 0: chance += status_plus
            if rng.random() < chance:
                d = st_time * st["duration_mult"]
                boss_mark["k"] = st_kind; boss_mark["until"] = t + min(d, K["STATUS_MAX_TIME"]) * 0.5

    def wiz(t, el, b0):
        nonlocal reactions
        if not mark["el"] or mark["until"] <= t or mark["el"] == el:
            mark["el"] = el; mark["until"] = t + K["COMBO_MARK_TIME"]; return
        pair = {mark["el"], el}
        if t - win["at"] > 0.1 or t < win["at"]: win["at"] = t; win["n"] = 0
        if win["n"] >= K["COMBO_CAP"]: return
        win["n"] += 1
        mark["el"] = ""; mark["until"] = -1.0
        kindr = "vapor" if pair == {"water", "fire"} else ("conduct" if "water" in pair else "blaze")
        if "earth" in pair: kindr = "lava" if "fire" in pair else ("mud" if "water" in pair else "sand")
        share = {"vapor": 1.0, "conduct": 0.8, "blaze": 0.6, "lava": K["COMBO_LAVA"], "mud": K["COMBO_SIDE"], "sand": K["COMBO_SIDE"]}[kindr]
        dmg = b0 * K["COMBO_MULT"] * (1 + combo_dmg) * share
        push(t + 0.05, "react", (dmg, kindr))
        reactions += 1

    # ---- DoTs from skills, procs and pets (dots.gd burn_on / bleed_on / update / burst)
    burn = {"pool": 0.0, "time": 0.0, "heat": 0, "heat_at": 0.0, "heat_from": 0.0, "tag": "", "on": False}
    blood = {"v": 0.0, "n": 0, "tag": "", "end": -1.0}
    crowd = 1 + min(K["BURN_CROWD_MAX"], K["BURN_CROWD"] * 1)
    MAGIC_TAGS = set(_c(g, "MAGIC_TAGS"))

    def int_share(tag):
        if tag in MAGIC_TAGS: return 1.0
        sid = tag.replace("proc:", "").split("@")[0]
        if sid not in SK: return 0.0
        return float(weights(sid).get("int", 0.0))

    def heat_gap(t):
        gp = K["BURN_HEAT_EVERY"] + K["BURN_HEAT_EVERY_PER"] * burn["heat"]
        return gp * (K["WEB_HEAT_EVERY"] if web_until > t else 1.0)

    def burn_on(t, base, tag, long=1.0, pool=-1.0):
        lit = burn["on"] and burn["time"] > t
        dur = K["BURN_TIME"] * (1 + eff.get("burn_time", 0.0)) * long
        add = pool if pool >= 0 else base * K["BURN_IGNITE"] * (1 + K["BURN_MAGIC"] * int_share(tag)) * (1 + eff.get("burn_power", 0.0)) * dur / K["BURN_TIME"]
        if add <= 0: return
        if not lit:
            burn.update(pool=0.0, heat=int(eff.get("burn_heat_start", 0)), heat_from=t, on=True)
            burn["heat_at"] = t + heat_gap(t)
            push(t + 0.5, "burn_tick", None)
        elif t >= burn["heat_at"]:
            burn["heat"] += 1; burn["heat_at"] = t + heat_gap(t); burn["heat_from"] = t
        else:
            gp = heat_gap(t)
            burn["heat_at"] = max(burn["heat_from"] + gp / K["BURN_HEAT_HASTE"], burn["heat_at"] - gp * K["BURN_HEAT_PUSH"])
        burn["pool"] += add; burn["time"] = max(burn["time"], t + dur); burn["tag"] = tag

    pois = {"n": 0, "dps": 0.0, "end": -1.0, "tag": ""}
    p_cap = round(K["POISON_MAX_STACKS"] * (1 + eff.get("poison_cap", 0)))
    p_top = K["POISON_GROW_MAX"] * (1 + K["POISON_GROW_PER_CAP"] * eff.get("poison_cap", 0))

    def poison_on(t, dps, dur, tag):              # main.gd::apply_poison (doses x (1+poison_stack), keep the strongest dps)
        on = pois["end"] > t
        doses = 1 + int(eff.get("poison_stack", 0))
        pois["n"] = min(p_cap, (pois["n"] if on else 0) + doses)
        if not on or dps >= pois["dps"]: pois["dps"] = dps; pois["tag"] = tag
        pois["end"] = max(pois["end"], t + dur)
        if not on: push(t + 0.5, "poison_tick", None)

    def bleed_on(t, base, tag, stacks=1):
        blood["v"] += base * K["BLEED_STORE"] * stacks * (1 + eff.get("bleed_power", 0.0))
        blood["n"] += stacks; blood["tag"] = tag; blood["end"] = t + K["BLEED_TIME"]
        if blood["n"] >= max(1, K["BLEED_BURST_AT"] - int(eff.get("bleed_at", 0))): bleed_burst(t)
        else: push(blood["end"], "bleed_due", blood["end"])

    def bleed_burst(t):
        dmg = blood["v"] * K["BLEED_BURST_MULT"] * (1 + eff.get("bleed_dmg", 0.0)); tag = blood["tag"]
        blood.update(v=0.0, n=0, end=-1.0)
        if dmg > 0: hit(t, dmg, "neutral", tag, False, source="poison", can_crit=True)

    casts = {}
    while ev:
        t, _, k, p = heapq.heappop(ev)
        if k == "cast":
            sid, lv, tag, own = p
            s = SK[sid]
            stt = (s["status"], float(sv(g, sid, "status_chance", lv)) if "status_chance" in s or "per_level" in s else 0.0,
                   float(s.get("status_time", 2.0))) if s.get("status") else None
            for d, dmg, el, what in cast_hits(g, st, sid, lv, tag, rng=rng):
                push(t + d, "hit", (dmg, el, tag, bool(s.get("magic")), stt, what))
            casts[tag] = casts.get(tag, 0) + 1
            # double / multi cast (player.gd::_double_cast), also for Hindsight casts
            extra = multi_casts(multi_chance(sid)) if own != "echo" else 0
            for i in range(extra):
                push(t + K["INT_DOUBLE_DELAY"] * (i + 1), "copy", (sid, lv, tag))
            if own is True:
                for o in active:          # cut_cooldowns(chain_cut(), capped) before this skill's own cooldown is set
                    if o == sid or chain <= 0: continue
                    room = cdf[o] * K["CHAIN_CUT_MAX"] - cut[o]
                    c = min(chain, max(0.0, room))
                    if c > 0 and due_at[o] > t:
                        nxt[o] -= c; cut[o] += c; due_at[o] = max(t, nxt[o]); push(due_at[o], "due", o)
                cut[sid] = 0.0; nxt[sid] = t + cdf[sid]; due_at[sid] = nxt[sid]
                push(nxt[sid], "due", sid)
        elif k == "copy":
            sid, lv, tag = p
            s = SK[sid]
            stt = (s["status"], float(sv(g, sid, "status_chance", lv)), float(s.get("status_time", 2.0))) if s.get("status") else None
            for d, dmg, el, what in cast_hits(g, st, sid, lv, tag, rng=rng):
                push(t + d, "hit", (dmg, el, tag, bool(s.get("magic")), stt, what))
            casts[tag + " (copy)"] = casts.get(tag + " (copy)", 0) + 1
        elif k == "due":
            sid = p
            if abs(due_at[sid] - t) > 1e-9: continue          # stale: chain cast moved it
            push(t, "cast", (sid, skills[sid], sid, True))
        elif k == "hit":
            dmg, el, tag, magic, stt, what = p
            hit(t, dmg, el, tag, magic and tag != "hindsight", stt)
            if what == "web": web_until = max(web_until, t + K["WEB_FIRE_TIME"])
            elif isinstance(what, tuple) and what[0] == "poison":     # skills.gd::_melee_arc: apply_poison(dmg x POISON_DPS)
                poison_on(t, dmg * K["POISON_DPS"], what[1], tag)
        elif k == "react":
            dmg, kindr = p
            hit(t, dmg, "neutral", "wiz_combo", False)
            if kindr == "blaze":                      # main.gd _wiz_react "blaze": marks what it hits with fire
                mark["el"] = "fire"; mark["until"] = t + K["COMBO_MARK_TIME"]
        elif k == "swing":
            for bp in blows:                      # player.gd::on_basic_hit runs once per landed blow
                if hs > 0 and t >= hs_ready and rng.random() < hs * proc_more:
                    hs_ready = t + K["HINDSIGHT_CD"]
                    lv = max(1, int(skills.get("hindsight", 1)))
                    hsid = rng.choice(list(_c(g, "HINDSIGHT_SKILLS")))
                    push(t, "cast", (hsid, lv, "hindsight", False))
                for pr in procs:
                    odds = float(pr["chance"]) * proc_more * bp
                    n = min(int(odds) + (1 if rng.random() < odds - int(odds) else 0), K["PROC_POWER_CASTS_MAX"])
                    for _ in range(n): push(t, "pcast", (pr["skill"], int(pr.get("level", 1)), False))
            push(t + st["delay"], "swing", None)
        elif k == "touch":                        # enemy.gd::_touch_heroes -> player.gd::_autocast_when_hit
            mult = 1 + eff.get("hit_proc", 0) + (K["STEEL_HIT_PROC"] if st.get("steel") else 0)
            if "retaliation" in st["pacts"]: mult += float(G["PACTS"]["retaliation"]["retaliate"]["chance"])
            for pr in procs_hit:
                key = pr["skill"]
                if t < hit_cd.get(key, 0.0): continue
                if rng.random() < float(pr["chance"]) * mult:
                    hit_cd[key] = t + K["HIT_ICD"]          # player.gd PROC_HIT_CD = GameData.HIT_ICD
                    push(t, "pcast", (key, int(pr.get("level", 1)), True))
            push(t + K["TOUCH_EVERY"], "touch", None)
        elif k == "pcast":                        # player.gd::_proc_cast
            skill, lv, when_hit = p
            cast_id = skill
            if skill + "_x" in skills: cast_id = skill + "_x"; lv = int(skills[cast_id])
            elif skill in skills: lv = max(lv, int(skills[skill]))
            sk = SK.get(cast_id, {})
            if sk.get("type") not in DAMAGE_TYPES or "damage" not in sk:
                skipped.add(cast_id); continue
            bake = 1.0
            if not when_hit:
                if t * 1000 < p_next.get(cast_id, -1):
                    p_saved[cast_id] = p_saved.get(cast_id, 0) + 1; continue
                gap = K["PROC_GROUND_GAP_MS"] if sk.get("type") == "ground" and "heal_amount" not in sk else K["PROC_GAP_MS"]
                p_next[cast_id] = t * 1000 + gap
                bake = (1 + p_saved.get(cast_id, 0)) ** K.get("PROC_HELD_POW", 1.0); p_saved[cast_id] = 0
            tag = "proc:" + skill + ("@hit" if when_hit else "")
            stt = (sk["status"], float(sv(g, cast_id, "status_chance", lv)), float(sk.get("status_time", 2.0))) if sk.get("status") else None
            for d, dmg, el, what in cast_hits(g, st, cast_id, lv, tag, bake, rng=rng):
                push(t + d, "hit", (dmg, el, tag, True, stt, what))
            casts[tag] = casts.get(tag, 0) + 1
        elif k == "pet":                          # main.gd::_pet_skill / _pet_hit, then sk.extra with it
            tag = "pet:" + str(b.get("pet"))
            for q in pet_parts(pet):
                kd = q.get("kind")
                if kd == "echo":                  # Thanatos: count of your attack skills (PET_ECHO_TYPES), own level, no double cast
                    ids = [i for i in skills if SK[i].get("type") in _c(g, "PET_ECHO_TYPES") and not SK[i].get("stance") and not SK[i].get("combo_only")]
                    rng.shuffle(ids); n_ok = 0
                    for i in ids:
                        if n_ok >= int(q.get("count", 1)): break
                        if SK[i].get("type") not in DAMAGE_TYPES: skipped.add("echo " + i); continue
                        push(t, "cast", (i, skills[i], tag + ":" + i, "echo")); n_ok += 1
                    continue
                if kd not in ("strikes", "nova") or float(q.get("dmg", 0) or 0) <= 0: continue
                dmg = float(q["dmg"]) * K["MVP_PET_DMG"] * (1 + K["MVP_PET_LEVEL_DMG"] * (st["L"] - 1))
                hit(t, dmg, q.get("element", "neutral"), tag, False)
                dot = q.get("dot", "")
                if dot == "burn": burn_on(t, dmg * K["BURN_ONCE"], tag)
                elif dot == "bleed": bleed_on(t, dmg, tag)
                elif dot == "poison": poison_on(t, dmg * K["POISON_DPS"], K["PET_DOT_POISON_TIME"], tag)
                if q.get("frail"):
                    pet_fr["v"] = max(pet_fr["v"] if pet_fr["until"] > t else 0.0, float(q["frail"])); pet_fr["until"] = t + K["PET_FRAIL_TIME"]
            push(t + float(pet["every"]), "pet", None)
        elif k == "poison_tick":                  # main.gd::_update_poison -> _poison_hit every 0.5 s
            if pois["n"] <= 0 or pois["end"] <= t - 1e-9: pois["n"] = 0; continue
            grow = min(p_top, (K["POISON_GROWTH"] + eff.get("poison_growth", 0)) ** (pois["n"] - 1))
            hit(t, pois["dps"] * K["POISON_FLAT"] * 0.5 * grow * (1 + eff.get("poison_dmg", 0)), "poison", pois["tag"], False, source="poison")
            push(t + 0.5, "poison_tick", None)
        elif k == "burn_tick":                    # dots.gd::update, every 0.5 s while burning
            if not burn["on"]: continue
            left = burn["time"] - t
            share = min(1.0, 0.5 / max(0.5, left + 0.5))
            part = burn["pool"] * share; burn["pool"] -= part
            if part > 0: hit(t, part * (1 + K["BURN_HEAT"] * burn["heat"]) * crowd, "fire", burn["tag"], False, source="poison")
            if left <= 0.5 + 1e-9: burn.update(on=False, pool=0.0, heat=0)
            else: push(t + 0.5, "burn_tick", None)
        elif k == "bleed_due":                    # BLEED_TIME s without a new cut: the blood bursts
            if blood["n"] > 0 and abs(blood["end"] - p) < 1e-9: bleed_burst(t)
    total = sum(parts.values())
    return dict(total=total, parts=parts, casts=casts, reactions=reactions, dragon=dragon, skipped=sorted(skipped))

