"""Carrega uma versão do jogo: constantes (K), tabelas de dados (G) e suposições (A)."""
import json, os


def _jload(path, encoding="utf-8"):
    with open(path, encoding="utf-8") as fh:
        return json.load(fh)

CALC = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
MODEL = os.path.dirname(CALC)


def latest_version():
    vs = [v for v in os.listdir(os.path.join(CALC, "versions")) if os.path.isdir(os.path.join(CALC, "versions", v))]
    return max(vs, key=lambda v: tuple(int(x) for x in v.split(".")))


class Consts:
    """Constantes de uma versão. Registra o que foi lido (para o diff saber o que cada build usa)."""

    def __init__(self, table):
        self._t = table; self.seen = set()

    def __getitem__(self, k):
        self.seen.add(k)
        if k not in self._t: raise KeyError("constante %s não existe nesta versão" % k)
        v = self._t[k]["value"]
        if v is None: raise KeyError("constante %s MISSING (anchors.json não casou: a fórmula mudou?)" % k)
        return v

    def get(self, k, default):
        """Para regras que só existem a partir de certa versão (ex.: PROC_HELD_POW, ausente no 0.2.7 = 1.0)."""
        self.seen.add(k)
        e = self._t.get(k)
        return default if e is None or e["value"] is None else e["value"]

    def __contains__(self, k):
        self.seen.add(k)
        return k in self._t and self._t[k]["value"] is not None

    def where(self, k):
        return self._t.get(k, {}).get("at", "?")


class Game:
    def __init__(self, version=None, track=False):
        self.version = version or latest_version()
        vdir = os.path.join(CALC, "versions", self.version)
        if not os.path.isdir(vdir):
            raise SystemExit("versão %s não extraída: rode py -3.14 calc/extract.py %s" % (self.version, self.version))
        self.K = Consts(_jload(os.path.join(vdir, "constants.json"), encoding="utf-8"))
        src = _jload(os.path.join(CALC, "sources.json"), encoding="utf-8")[self.version]
        self.G = _jload(os.path.join(MODEL, src["data"]), encoding="utf-8")["game_data"]
        self.A = {k: v["value"] for k, v in _jload(os.path.join(CALC, "assumptions.json"), encoding="utf-8").items()
                  if not k.startswith("_")}
        self.sources = set()

    def use(self, module):
        from . import ENGINE_SOURCES
        self.sources.update(ENGINE_SOURCES[module])

