"""equipment.gd / potential.gd: mods e efeitos de cada peça.

Item no formato do save: {id, cards[], slots, refine, grade, pot{lines[{k,t,p}]}, trait, hel}.
"""
from .stats import add


def wing_fx(g, r):
    """game_data.gd::wing_fx (só os campos que afetam dano/atributo)."""
    fx = {}; cap = (2 if r >= 1 else 0) + (2 if r >= 4 else 0) + (5 if r >= 10 else 0)
    if cap: fx["wing_stat_cap"] = float(cap)
    if r >= 3: fx["wing_card"] = .3 if r >= 8 else .15
    if r >= 7: fx["wing_fill"] = .25
    if r >= 9: fx["wing_broken"] = .2
    return fx


def item_def(g, it):
    return g.G["ITEMS"][it["id"]]


def item_type(g, it):
    return item_def(g, it)["slot"]


def refine_safe(g, it):
    """equipment.gd::refine_safe"""
    d = item_def(g, it)
    if d["slot"] == "weapon":
        wl = d.get("wlv") or (4 if d.get("legendary") else min(4, int(d.get("rank", 1)) + 1))
        tab = g.G["REFINE_RATES"]["w%d" % wl]
    else:
        tab = g.G["REFINE_RATES"]["armor"]
    n = 0
    while n < len(tab) and tab[n] >= 1: n += 1
    return n


def two_hands(g, it):
    """equipment.gd::two_hands / game_data.gd::two_handed"""
    return item_type(g, it) == "weapon" and g.G["WEAPON_KINDS"].get(it["id"], "") in g.G.get("TWO_HANDED_KINDS", [])


def pot_value(g, l):
    """potential.gd::value"""
    vals = g.G["POTENTIAL_LINES"][l["k"]]["vals"]; n = len(g.G["POTENTIAL_TIERS"])
    i = max(1, min(int(l.get("t", n)), n)) - 1
    if i >= n - 1 and l.get("p"): i += 1
    return vals[min(i, len(vals) - 1)]


def pot_lines(g, it):
    return [l for l in (it.get("pot") or {}).get("lines", []) if l.get("k") in g.G["POTENTIAL_LINES"]][:3]


def item_mods(g, it):
    """equipment.gd::item_mods + _base_mods"""
    K, G = g.K, g.G
    d = item_def(g, it); out = {}; r = int(it.get("refine", 0))
    mult = G["ITEM_TIERS"][max(0, min(3, int(it.get("slots", 0))))]["mult"]
    step = K["REFINE_STAT_STEP"]; slow = K.get("REFINE_SLOW_GROWTH", {})
    hel = it.get("hel") and d.get("wings")
    for k, v in (d.get("mods") or {}).items():
        v = v * mult
        if hel and v > 0 and k not in G["HEL_WINGS_KEEP"]: v *= K["HEL_WINGS_MULT"]
        gr = 1 + step * r if "refine" in d else 1.0
        if k in slow and "refine" in d: gr = 1 + step * slow[k] * r
        out[k] = out.get(k, 0) + (v * gr if v > 0 else v)
    for k, v in (d.get("refine") or {}).items(): out[k] = out.get(k, 0) + v * r
    over = r - refine_safe(g, it)
    if d["slot"] == "weapon" and over > 0: out["dmg"] = out.get("dmg", 0) + K["REFINE_OVER_DMG"] * over
    for l in pot_lines(g, it):
        p = G["POTENTIAL_LINES"][l["k"]]
        if "mod" in p: out[p["mod"]] = out.get(p["mod"], 0) + pot_value(g, l)
    if two_hands(g, it):
        for k in out:
            if out[k] > 0: out[k] *= 1 + K["TWO_HANDED_BONUS"]
    gr = int(it.get("grade", 0))
    if gr and d["slot"] == "weapon": out["grade_mult"] = out.get("grade_mult", 0) + G["WEAPON_GRADES"][gr]["dmg"]
    elif gr and d["slot"] in G["GEAR_GRADES"]:
        gg = G["GEAR_GRADES"][d["slot"]]
        for k in gg["keys"]: out[k] = out.get(k, 0) + gg["vals"][gr]
    ck = 1.0 + (wing_fx(g, r).get("wing_card", 0) if d.get("wings") else 0)
    for c in it.get("cards", []):
        for k, v in (G["CARDS"][c].get("mods") or {}).items(): out[k] = out.get(k, 0) + (v * ck if v > 0 else v)
    return out


def item_fx(g, it, worn_ids):
    """Efeitos da peça (alma, asas, traço roxo, linhas de potencial com fx)."""
    G = g.G; d = item_def(g, it)
    if d.get("soul_of"):
        src = d["soul_of"]
        if src in worn_ids: return {}            # soul_active: não vale usando o próprio item
        fx = dict(G["ITEMS"][src].get("effects") or {})
    else:
        fx = dict(d.get("effects") or {})
    if d.get("wings"): add(fx, wing_fx(g, int(it.get("refine", 0))))
    t = it.get("trait")
    if t in G["PURPLE_TRAITS"]:
        tier = max(1, min(3, int(it.get("slots", 0))))
        for k, vals in G["PURPLE_TRAITS"][t]["fx"].items(): fx[k] = fx.get(k, 0) + vals[min(tier, len(vals)) - 1]
    for l in pot_lines(g, it):
        for k in G["POTENTIAL_LINES"][l["k"]].get("fx", []): fx[k] = fx.get(k, 0) + pot_value(g, l)
    return fx


def proc_of(g, it):
    d = item_def(g, it)
    if d.get("soul_of"): d = g.G["ITEMS"][d["soul_of"]]
    return d.get("proc"), d.get("proc_hit")

