"""Procs: quais procs a build tem, a regra de carta de skill própria (0.2.8+) e o empacotamento no gap de 100 ms."""
from .gear import proc_of


def card_merges(g, skill):
    """game_data.gd::card_merges. Só existe a partir do 0.2.8 (CARD_OWN_SKILL_DMG); antes, toda carta lança a skill."""
    if "CARD_OWN_SKILL_DMG" not in g.K: return False
    s = g.G["SKILLS"].get(skill, {})
    if "damage" not in s or skill in g.G.get("CARD_SKILL_CAST", []): return False
    return s.get("type", "") not in ("heal", "shield", "buff", "summon")


def card_procs(g, b, gear, album, sockets):
    """Ordem do jogo: cartas do álbum, cartas encaixadas, depois itens. Devolve (procs, procs_ao_ser_tocado, bônus_de_skill).
    0.2.8: carta que lançaria uma skill que você já tem (ou o EX) não lança; vira +CARD_OWN_SKILL_DMG × chance de dano nela."""
    g.use("procs")
    C = g.G["CARDS"]; own = set(b["skills"])
    procs, hits, bonus = [], [], {}
    owns = lambda sk: sk in own or sk + "_x" in own
    for c in album + sockets:
        for key, out in (("proc", procs), ("proc_hit", hits)):
            p = C[c].get(key)
            if not p: continue
            if owns(p["skill"]) and card_merges(g, p["skill"]):
                bonus[p["skill"]] = bonus.get(p["skill"], 0) + float(p["chance"]) * g.K["CARD_OWN_SKILL_DMG"]
            else:
                out.append(p)
    for it in gear.values():
        p, ph = proc_of(g, it)
        if p: procs.append(p)
        if ph: hits.append(ph)
    return procs, hits, bonus


def expected_casts(g, st, skill):
    """Lançamentos esperados por golpe (on_basic_hit): chance × (1+proc_chance) × poder do golpe, teto PROC_POWER_CASTS_MAX."""
    cap = g.K["PROC_POWER_CASTS_MAX"]
    return sum(min(float(cap), p["chance"] * st["proc_more"] * st["power"]) for p in st["procs"] if p["skill"] == skill)


def held(g, saved):
    """player.gd::_proc_cast: os lançamentos guardados no gap valem (1+saved)^PROC_HELD_POW (0.2.7: sem expoente)."""
    return (1 + saved) ** g.K.get("PROC_HELD_POW", 1.0)

