"""Fórmulas básicas: nível de skill acima do máximo, proc_level_mult, haste suave, keep do ASPD, cap de atributo."""


def overlevel_steps(g, over):
    """game_data.gd::overlevel_steps"""
    K = g.K; full, half = K["OVERLEVEL_FULL"], K["OVERLEVEL_HALF"]
    if over <= full: return float(over)
    if over <= half: return full + (over - full) * 0.5
    return full + (half - full) * 0.5 + (over - half) * 0.25


def skill_cap(g, sid):
    """game_data.gd::skill_cap"""
    return 1 if g.G["SKILLS"][sid].get("evolved") else g.K["MAX_SKILL_LEVEL"]


def skill_value(g, sid, field, lv):
    """game_data.gd::skill_value"""
    s = g.G["SKILLS"][sid]; per = s.get("per_level") or {}
    top = skill_cap(g, sid)
    v = float(s.get(field, 0.0)) + float(per.get(field, 0.0)) * (min(lv, top) - 1)
    if lv > top and field in (s.get("over_add") or {}): return v + s["over_add"][field] * (lv - top)
    if lv > top and field in (s.get("over_never") or []): return v
    if lv > top and (field in g.G["OVERLEVEL_FIELDS"] or field in (s.get("bonus") or [])) and field not in g.G["OVERLEVEL_NEVER"]:
        # 0.2.10 game_data.gd:9308 skill_value: "damage" uses over_dmg_step when the skill has one (falcon, traps, archer EX)
        step = s.get("over_dmg_step", s.get("over_step", g.K["OVERLEVEL_STEP"])) if field == "damage" else s.get("over_step", g.K["OVERLEVEL_STEP"])
        if step is None: step = g.K["BOLT_EX_STEP"]   # the data dump loses const refs: Fire/Cold Bolt EX and Soul Strike EX use BOLT_EX_STEP
        v *= 1 + float(step) * overlevel_steps(g, lv - top)
    elif lv > top and field in g.G.get("OVERLEVEL_SHRINK", []):
        v /= 1 + g.K["OVERLEVEL_STEP"] * overlevel_steps(g, lv - top)
    return v


def proc_level_mult(g, L):
    """game_data.gd::proc_level_mult"""
    K = g.K; soft = K["PROC_LEVEL_SOFT"]
    return 1 + K["PROC_LEVEL_DMG"] * (min(L, soft) - 1) + K["PROC_LEVEL_DMG_LATE"] * max(0, L - soft)


def soft_haste(g, h):
    """game_data.gd::soft_haste"""
    return h / (1 + max(0.0, h) / g.K["HASTE_SOFT"])


def keep(g, c):
    """player.gd::_keep"""
    knee = g.K["KEEP_KNEE"]
    return 1 - c if c <= knee else (1 - knee) / (1 + g.K["KEEP_SLOPE"] * (c - knee))


def capped(g, v, cap):
    """player.gd::_capped: até o cap vale 1, acima vale OVERSTAT_EFF."""
    return min(v, cap) + max(0.0, v - cap) * g.K["OVERSTAT_EFF"]


def add(d, src, k=1.0):
    for a, v in (src or {}).items():
        if isinstance(v, (int, float)) and not isinstance(v, bool): d[a] = d.get(a, 0.0) + v * k
